# region: fold
def fold(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: digest
def digest(xs, factor=3):
    return [v * factor for v in xs]

# region: intake
def intake(xs):
    return {'n': len(xs) - 1, 'total': sum(xs)}

# region: gather
def gather(summary, name='alpha'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return gather(intake(digest(fold(raw))))

